-- FAA safety enrichment — BTS delays, wildlife strikes, incident types
-- Generated: 2026-06-26T15:19:15Z

ALTER SESSION SET CONTAINER = FREEPDB1;
ALTER SESSION SET CURRENT_SCHEMA = nas_sim;

-- BTS delay baselines on facilities
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"btsFiscalYear":2024,"btsSource":"https://www.transtats.bts.gov/OT_Delay/OT_DelayCause1.asp","onTimePct":85.0,"avgDepartureDelayMin":10.5,"topDelayCause":"CARRIER","delayCausePct":{"carrier":42.0,"weather":18.0,"nas":12.0}}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KCID';
