-- FAA-inspired incident types (NAS Safety Review / wildlife patterns)
MERGE INTO incident_type_lkp t USING (SELECT 'WILDLIFE_STRIKE' AS incident_type_code FROM dual) s ON (t.incident_type_code = s.incident_type_code) WHEN NOT MATCHED THEN INSERT (incident_type_code, display_name, default_severity, behavior_json) VALUES ('WILDLIFE_STRIKE', 'Wildlife Strike', 'HIGH', q'[{"affectsActivityTypes":["PASSENGER_BOARDING"],"action":"PAUSE","delayMinutes":45,"faaInspired":true}]');
MERGE INTO incident_type_lkp t USING (SELECT 'NAS_EQUIPMENT_OUTAGE' AS incident_type_code FROM dual) s ON (t.incident_type_code = s.incident_type_code) WHEN NOT MATCHED THEN INSERT (incident_type_code, display_name, default_severity, behavior_json) VALUES ('NAS_EQUIPMENT_OUTAGE', 'NAS Equipment Outage', 'CRITICAL', q'[{"affectsActivityTypes":[],"action":"PAUSE","delayMinutes":60,"faaInspired":true,"anchor":"NAS Safety Review 2023"}]');
MERGE INTO incident_type_lkp t USING (SELECT 'NOTAM_SYSTEM_DEGRADED' AS incident_type_code FROM dual) s ON (t.incident_type_code = s.incident_type_code) WHEN NOT MATCHED THEN INSERT (incident_type_code, display_name, default_severity, behavior_json) VALUES ('NOTAM_SYSTEM_DEGRADED', 'NOTAM System Degraded', 'HIGH', q'[{"affectsActivityTypes":[],"action":"PAUSE","delayMinutes":30,"faaInspired":true}]');

-- Global config: FAA ingest provenance
MERGE INTO global_configuration t USING (SELECT 'faa.ingest.last_cycle' AS config_key FROM dual) s ON (t.config_key = s.config_key) WHEN MATCHED THEN UPDATE SET config_value = '2026-06-11', updated_at = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (config_key, config_value, description) VALUES ('faa.ingest.last_cycle', '2026-06-11', 'Last applied NASR 28-day cycle');
MERGE INTO global_configuration t USING (SELECT 'faa.ingest.phases' AS config_key FROM dual) s ON (t.config_key = s.config_key) WHEN MATCHED THEN UPDATE SET config_value = '107,108,109,110,111', updated_at = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (config_key, config_value, description) VALUES ('faa.ingest.phases', '107,108,109,110,111', 'Applied FAA overlay seed scripts');

COMMIT;
